-- -----------------------------------------------------------------------------
create table public.financial_documents (
  id uuid primary key default gen_random_uuid(),
  document_number bigint generated always as identity unique,
  document_type text not null
    check (document_type in ('receipt','payment','transfer','adjustment')),
  transaction_date date not null,
  branch_id uuid references public.church_branches(id) on delete restrict,
  profile_id uuid references public.profiles(id) on delete restrict,
  payee_or_payer_name text not null,
  amount numeric(20,4) not null check (amount > 0),
  currency_code char(3) not null references public.currencies(code),
  payment_method text not null
    check (payment_method in ('cash','bank_transfer','mobile_money','card','cheque','other')),
  financial_account_id uuid references public.financial_accounts(id) on delete restrict,
  external_reference text,
  description text,
  status text not null default 'draft'
    check (status in ('draft','pending_approval','approved','rejected','posted','cancelled')),
  journal_entry_id uuid unique
    references public.journal_entries(id) on delete restrict,
  approval_request_id uuid,
  created_by_profile_id uuid references public.profiles(id) on delete set null,
  approved_by_profile_id uuid references public.profiles(id) on delete set null,
  approved_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint financial_document_party_nonblank
    check (length(trim(payee_or_payer_name)) > 0),
  constraint financial_document_approval_consistency check (
    (status = 'approved' and approved_at is not null)
    or status <> 'approved'
  ),
  constraint financial_document_posted_has_journal check (
    status <> 'posted' or journal_entry_id is not null
  )
);
create index ix_financial_documents_date
  on public.financial_documents (transaction_date desc);
create index ix_financial_documents_branch_date
  on public.financial_documents (branch_id, transaction_date desc);
create index ix_financial_documents_profile
  on public.financial_documents (profile_id) where profile_id is not null;
create index ix_financial_documents_account
  on public.financial_documents (financial_account_id)
  where financial_account_id is not null;
create index ix_financial_documents_journal
  on public.financial_documents (journal_entry_id)
  where journal_entry_id is not null;
create index ix_financial_documents_created_by
  on public.financial_documents (created_by_profile_id)
  where created_by_profile_id is not null;
create index ix_financial_documents_approved_by
  on public.financial_documents (approved_by_profile_id)
  where approved_by_profile_id is not null;

create table public.giving_records (
  id uuid primary key default gen_random_uuid(),
  financial_document_id uuid not null unique
    references public.financial_documents(id) on delete restrict,
  giver_profile_id uuid references public.profiles(id) on delete set null,
  giver_name text not null,
  giving_type text not null
    check (giving_type in ('tithe','offering','donation','pledge','other')),
  fund_id uuid references public.funds(id) on delete restrict,
  campaign_or_appeal text,
  created_at timestamptz not null default now(),
  constraint giving_record_giver_name_nonblank
    check (length(trim(giver_name)) > 0)
);
create index ix_giving_records_giver
  on public.giving_records (giver_profile_id)
  where giver_profile_id is not null;
create index ix_giving_records_fund
  on public.giving_records (fund_id)
  where fund_id is not null;

create table public.budgets (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  budget_type text not null
    check (budget_type in ('annual','monthly','department','event','other')),
  branch_id uuid references public.church_branches(id) on delete restrict,
  event_id uuid references public.events(id) on delete restrict,
  period_id uuid not null references public.financial_periods(id) on delete restrict,
  currency_code char(3) not null references public.currencies(code),
  status text not null default 'draft'
    check (status in ('draft','pending_approval','approved','rejected','closed')),
  submitted_by_profile_id uuid references public.profiles(id) on delete set null,
  approved_by_profile_id uuid references public.profiles(id) on delete set null,
  approved_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint budget_name_nonblank check (length(trim(name)) > 0),
  constraint budget_approval_consistency check (
    (status = 'approved' and approved_at is not null)
    or status <> 'approved'
  )
);
create index ix_budgets_period on public.budgets (period_id);
create index ix_budgets_branch_period on public.budgets (branch_id, period_id);
create index ix_budgets_event on public.budgets (event_id) where event_id is not null;
create index ix_budgets_submitted_by on public.budgets (submitted_by_profile_id)
  where submitted_by_profile_id is not null;
create index ix_budgets_approved_by on public.budgets (approved_by_profile_id)
  where approved_by_profile_id is not null;

create table public.budget_lines (
  id uuid primary key default gen_random_uuid(),
  budget_id uuid not null references public.budgets(id) on delete restrict,
  account_id uuid references public.chart_of_accounts(id) on delete restrict,
  fund_id uuid references public.funds(id) on delete restrict,
  description text,
  allocated_amount numeric(20,4) not null check (allocated_amount >= 0),
  created_at timestamptz not null default now()
);
create index ix_budget_lines_budget on public.budget_lines (budget_id);
create index ix_budget_lines_account on public.budget_lines (account_id)
  where account_id is not null;
create index ix_budget_lines_fund on public.budget_lines (fund_id)
  where fund_id is not null;

create table public.payment_gateway_transactions (
  id uuid primary key default gen_random_uuid(),
  financial_document_id uuid
    references public.financial_documents(id) on delete restrict,
  provider text not null,
  provider_transaction_id text,
  idempotency_key text,
  amount numeric(20,4) not null check (amount > 0),
  currency_code char(3) not null references public.currencies(code),
  status text not null default 'initiated'
    check (status in ('initiated','pending','successful','failed','cancelled','refunded')),
  received_at timestamptz,
  created_at timestamptz not null default now(),
  constraint payment_gateway_provider_nonblank check (length(trim(provider)) > 0)
);
create unique index uq_payment_gateway_provider_transaction
  on public.payment_gateway_transactions (provider, provider_transaction_id)
  where provider_transaction_id is not null;
create unique index uq_payment_gateway_idempotency
  on public.payment_gateway_transactions (idempotency_key)
  where idempotency_key is not null;
create index ix_payment_gateway_document
  on public.payment_gateway_transactions (financial_document_id)
  where financial_document_id is not null;
create index ix_payment_gateway_status_created
  on public.payment_gateway_transactions (status, created_at desc);

create table private.payment_gateway_payloads (
  id uuid primary key default gen_random_uuid(),
  transaction_id uuid not null
    references public.payment_gateway_transactions(id) on delete restrict,
  provider_payload jsonb not null,
  received_at timestamptz not null default now()
);
alter table private.payment_gateway_payloads enable row level security;
revoke all on private.payment_gateway_payloads
  from public, anon, authenticated, service_role;
create policy payment_gateway_payloads_deny_all
on private.payment_gateway_payloads for all to public
using (false) with check (false);

alter table public.financial_documents enable row level security;
alter table public.giving_records enable row level security;
alter table public.budgets enable row level security;
alter table public.budget_lines enable row level security;
alter table public.payment_gateway_transactions enable row level security;

revoke all on public.financial_documents, public.giving_records,
  public.budgets, public.budget_lines, public.payment_gateway_transactions
from anon, authenticated;
grant select on public.financial_documents, public.giving_records,
  public.budgets, public.budget_lines, public.payment_gateway_transactions
to authenticated;

create policy financial_documents_finance_or_party_read
on public.financial_documents for select to authenticated
using (
  (branch_id is null and private.has_permission('view_finances', null))
  or (branch_id is not null and private.has_permission('view_finances', branch_id))
  or profile_id = private.current_profile_id()
);

create policy giving_records_finance_or_giver_read
on public.giving_records for select to authenticated
using (
  giver_profile_id = private.current_profile_id()
  or exists (
    select 1 from public.financial_documents fd
    where fd.id = financial_document_id
      and (
        (fd.branch_id is null and private.has_permission('view_finances', null))
        or (fd.branch_id is not null and private.has_permission('view_finances', fd.branch_id))
      )
  )
);

create policy budgets_finance_read
on public.budgets for select to authenticated
using (
  (branch_id is null and private.has_permission('view_finances', null))
  or (branch_id is not null and private.has_permission('view_finances', branch_id))
);

create policy budget_lines_finance_read
on public.budget_lines for select to authenticated
using (
  exists (
    select 1 from public.budgets b
    where b.id = budget_id
  )
);

create policy payment_gateway_finance_read
on public.payment_gateway_transactions for select to authenticated
using (
  exists (
    select 1 from public.financial_documents fd
    where fd.id = financial_document_id
      and (
        (fd.branch_id is null and private.has_permission('view_finances', null))
        or (fd.branch_id is not null and private.has_permission('view_finances', fd.branch_id))
      )
  )
  or private.has_permission('view_finances', null)
);

-- -----------------------------------------------------------------------------
-- Baseline-only reconciliation: complete financial-document currency fields
-- -----------------------------------------------------------------------------
alter table public.financial_documents
  add column exchange_rate_to_base numeric(20,8) not null default 1,
  add column base_currency_code char(3) not null default 'SLE' references public.currencies(code);

alter table public.financial_documents
  add constraint financial_documents_exchange_rate_to_base_check
    check (exchange_rate_to_base > 0),
  add constraint financial_document_base_rate
    check (currency_code <> base_currency_code or exchange_rate_to_base = 1);

-- -----------------------------------------------------------------------------
-- 20261114142400_scms_015_threshold_approval_schema.sql
-- -----------------------------------------------------------------------------
set local search_path = public, extensions;

create table public.approval_policies (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  transaction_type text not null
    check (transaction_type in ('financial_document','journal_entry','budget','requisition')),
  branch_id uuid references public.church_branches(id) on delete restrict,
  version integer not null check (version > 0),
  effective_from date not null,
  effective_to date,
  is_active boolean not null default true,
  created_by_profile_id uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  constraint approval_policy_effective_dates check (
    effective_to is null or effective_to >= effective_from
  ),
  constraint approval_policy_name_nonblank check (length(trim(name)) > 0)
);
create unique index uq_approval_policy_version_scope
  on public.approval_policies (
    transaction_type,
    coalesce(branch_id, '00000000-0000-0000-0000-000000000000'::uuid),
    version
  );
create index ix_approval_policies_active_scope
  on public.approval_policies (transaction_type, branch_id, is_active, effective_from);

create table public.approval_policy_bands (
  id uuid primary key default gen_random_uuid(),
  policy_id uuid not null references public.approval_policies(id) on delete restrict,
  min_amount_base numeric(20,4) not null default 0
    check (min_amount_base >= 0),
  max_amount_base numeric(20,4),
  created_at timestamptz not null default now(),
  constraint approval_band_range check (
    max_amount_base is null or max_amount_base > min_amount_base
  ),
  constraint approval_bands_no_overlap
    exclude using gist (
      policy_id with =,
      numrange(min_amount_base, max_amount_base, '[)') with &&
    )
);
create index ix_approval_policy_bands_policy
  on public.approval_policy_bands (policy_id);

create table public.approval_policy_steps (
  id uuid primary key default gen_random_uuid(),
  band_id uuid not null references public.approval_policy_bands(id) on delete restrict,
  step_number integer not null check (step_number > 0),
  required_permission_key text not null
    references public.permissions(key) on update cascade on delete restrict,
  required_approvals integer not null default 1
    check (required_approvals > 0),
  prohibit_submitter_approval boolean not null default true,
  created_at timestamptz not null default now(),
  unique (band_id, step_number)
);

create table public.approval_requests (
  id uuid primary key default gen_random_uuid(),
  transaction_type text not null
    check (transaction_type in ('financial_document','journal_entry','budget','requisition')),
  target_id uuid not null,
  branch_id uuid references public.church_branches(id) on delete restrict,
  policy_id uuid references public.approval_policies(id) on delete restrict,
  policy_version integer,
  band_id uuid references public.approval_policy_bands(id) on delete restrict,
  amount_base numeric(20,4) not null check (amount_base >= 0),
  status text not null default 'pending'
    check (status in ('pending','approved','rejected','cancelled')),
  submitted_by_profile_id uuid not null
    references public.profiles(id) on delete restrict,
  submitted_at timestamptz not null default now(),
  completed_at timestamptz,
  policy_snapshot jsonb not null default '{}'::jsonb,
  constraint approval_request_completion check (
    (status in ('approved','rejected','cancelled') and completed_at is not null)
    or status = 'pending'
  )
);
create unique index uq_approval_request_one_pending_target
  on public.approval_requests (transaction_type, target_id)
  where status = 'pending';
create index ix_approval_requests_branch_status
  on public.approval_requests (branch_id, status, submitted_at desc);
create index ix_approval_requests_submitter
  on public.approval_requests (submitted_by_profile_id, submitted_at desc);

create table public.approval_request_steps (
  id uuid primary key default gen_random_uuid(),
  approval_request_id uuid not null
    references public.approval_requests(id) on delete restrict,
  step_number integer not null check (step_number > 0),
  required_permission_key text not null
    references public.permissions(key) on update cascade on delete restrict,
  required_approvals integer not null check (required_approvals > 0),
  prohibit_submitter_approval boolean not null default true,
  status text not null default 'pending'
    check (status in ('pending','approved','rejected')),
  created_at timestamptz not null default now(),
  unique (approval_request_id, step_number)
);
create index ix_approval_request_steps_request
  on public.approval_request_steps (approval_request_id, step_number);

create table public.approval_decisions (
  id uuid primary key default gen_random_uuid(),
  approval_request_step_id uuid not null
    references public.approval_request_steps(id) on delete restrict,
  approver_profile_id uuid not null
    references public.profiles(id) on delete restrict,
  decision text not null check (decision in ('approved','rejected')),
  comments text,
  decided_at timestamptz not null default now(),
  unique (approval_request_step_id, approver_profile_id)
);
create index ix_approval_decisions_approver
  on public.approval_decisions (approver_profile_id, decided_at desc);

alter table public.financial_documents
  add column exchange_rate_to_base numeric(20,8) not null default 1
    check (exchange_rate_to_base > 0),
  add column base_currency_code char(3) not null default 'SLE'
    references public.currencies(code),
  add constraint financial_document_base_rate check (
    currency_code <> base_currency_code or exchange_rate_to_base = 1
  ),
  add constraint financial_documents_approval_request_fk
    foreign key (approval_request_id)
    references public.approval_requests(id) on delete restrict;

alter table public.budgets
  add column exchange_rate_to_base numeric(20,8) not null default 1
    check (exchange_rate_to_base > 0),
  add column base_currency_code char(3) not null default 'SLE'
    references public.currencies(code),
  add column approval_request_id uuid
    references public.approval_requests(id) on delete restrict,
  add constraint budget_base_rate check (
    currency_code <> base_currency_code or exchange_rate_to_base = 1
  );

alter table public.journal_entries
  add column approval_request_id uuid
    references public.approval_requests(id) on delete restrict;

alter table public.approval_policies enable row level security;
alter table public.approval_policy_bands enable row level security;
alter table public.approval_policy_steps enable row level security;
alter table public.approval_requests enable row level security;
alter table public.approval_request_steps enable row level security;
alter table public.approval_decisions enable row level security;

revoke all on public.approval_policies, public.approval_policy_bands,
  public.approval_policy_steps, public.approval_requests,
  public.approval_request_steps, public.approval_decisions
from anon, authenticated;
grant select on public.approval_policies, public.approval_policy_bands,
  public.approval_policy_steps, public.approval_requests,
  public.approval_request_steps, public.approval_decisions
to authenticated;

create policy approval_policies_finance_read
on public.approval_policies for select to authenticated
using (
  (branch_id is null and private.has_permission('approve_finances', null))
  or (branch_id is not null and private.has_permission('approve_finances', branch_id))
  or (branch_id is null and private.has_permission('manage_finances', null))
  or (branch_id is not null and private.has_permission('manage_finances', branch_id))
);

create policy approval_policy_bands_finance_read
on public.approval_policy_bands for select to authenticated
using (
  exists (
    select 1 from public.approval_policies p
    where p.id = policy_id
  )
);

create policy approval_policy_steps_finance_read
on public.approval_policy_steps for select to authenticated
using (
  exists (
    select 1
    from public.approval_policy_bands b
    join public.approval_policies p on p.id = b.policy_id
    where b.id = band_id
  )
);

create policy approval_requests_submitter_or_approver_read
on public.approval_requests for select to authenticated
using (
  submitted_by_profile_id = private.current_profile_id()
  or (
    branch_id is null
    and (
      private.has_permission('approve_finances', null)
      or private.has_permission('manage_finances', null)
    )
  )
  or (
    branch_id is not null
    and (
      private.has_permission('approve_finances', branch_id)
      or private.has_permission('manage_finances', branch_id)
    )
  )
);

create policy approval_request_steps_parent_read
on public.approval_request_steps for select to authenticated
using (
  exists (
    select 1 from public.approval_requests r
    where r.id = approval_request_id
  )
);

create policy approval_decisions_parent_read
on public.approval_decisions for select to authenticated
using (
  exists (
    select 1
    from public.approval_request_steps s
    where s.id = approval_request_step_id
  )
);

-- -----------------------------------------------------------------------------
-- 20261114142439_scms_016_financial_approval_and_posting_workflows.sql
-- -----------------------------------------------------------------------------
create or replace function private.submit_financial_document_for_approval(
  p_document_id uuid
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_doc public.financial_documents%rowtype;
  v_profile_id uuid;
  v_base_currency char(3);
  v_policy public.approval_policies%rowtype;
  v_band public.approval_policy_bands%rowtype;
  v_request_id uuid;
  v_amount_base numeric(20,4);
  v_steps_count integer;
begin
  if (select auth.uid()) is null then
    raise exception 'Authentication required';
  end if;

  v_profile_id := private.current_profile_id();
  if v_profile_id is null then
    raise exception 'No member profile is linked to this account';
  end if;

  select * into v_doc
  from public.financial_documents
  where id = p_document_id
  for update;

  if not found then raise exception 'Financial document not found'; end if;
  if v_doc.status not in ('draft','rejected') then
    raise exception 'Only draft or rejected documents can be submitted';
  end if;
  if v_doc.journal_entry_id is not null then
    raise exception 'Document is already linked to a journal entry';
  end if;

  if v_doc.created_by_profile_id <> v_profile_id
     and not private.has_permission('manage_finances', v_doc.branch_id) then
    raise exception 'Insufficient permission to submit this document';
  end if;

  select base_currency_code into v_base_currency
  from public.church_settings where id = 1;

  if v_base_currency is null then
    raise exception 'Church settings must be configured before financial operations';
  end if;
  if v_doc.base_currency_code <> v_base_currency then
    raise exception 'Document base currency does not match church base currency';
  end if;
  if v_doc.currency_code = v_base_currency and v_doc.exchange_rate_to_base <> 1 then
    raise exception 'Exchange rate must be 1 for the base currency';
  end if;

  if v_doc.financial_account_id is not null then
    if not exists (
      select 1 from public.financial_accounts fa
      where fa.id = v_doc.financial_account_id
        and fa.is_active
        and fa.currency_code = v_doc.currency_code
        and (fa.branch_id is null or fa.branch_id is not distinct from v_doc.branch_id)
    ) then
      raise exception 'Financial account is inactive or incompatible with document branch/currency';
    end if;
  end if;

  v_amount_base := round(v_doc.amount * v_doc.exchange_rate_to_base, 4);

  select * into v_policy
  from public.approval_policies p
  where p.transaction_type = 'financial_document'
    and p.is_active
    and p.effective_from <= current_date
    and (p.effective_to is null or p.effective_to >= current_date)
    and (p.branch_id = v_doc.branch_id or p.branch_id is null)
  order by (p.branch_id is not null) desc, p.version desc
  limit 1;

  if not found then
    update public.financial_documents
    set status = 'approved',
        approved_at = now(),
        approved_by_profile_id = null,
        approval_request_id = null
    where id = p_document_id;
    return null;
  end if;

  select * into v_band
  from public.approval_policy_bands b
  where b.policy_id = v_policy.id
    and v_amount_base >= b.min_amount_base
    and (b.max_amount_base is null or v_amount_base < b.max_amount_base)
  limit 1;

  if not found then
    update public.financial_documents
    set status = 'approved',
        approved_at = now(),
        approved_by_profile_id = null,
        approval_request_id = null
    where id = p_document_id;
    return null;
  end if;

  select count(*) into v_steps_count
  from public.approval_policy_steps
  where band_id = v_band.id;

  if v_steps_count = 0 then
    update public.financial_documents
    set status = 'approved',
        approved_at = now(),
        approved_by_profile_id = null,
        approval_request_id = null
    where id = p_document_id;
    return null;
  end if;

  insert into public.approval_requests (
    transaction_type, target_id, branch_id, policy_id, policy_version,
    band_id, amount_base, submitted_by_profile_id, policy_snapshot
  )
  values (
    'financial_document', p_document_id, v_doc.branch_id,
    v_policy.id, v_policy.version, v_band.id, v_amount_base,
    v_profile_id,
    jsonb_build_object(
      'policy_name', v_policy.name,
      'policy_version', v_policy.version,
      'min_amount_base', v_band.min_amount_base,
      'max_amount_base', v_band.max_amount_base,
      'steps', (
        select coalesce(jsonb_agg(jsonb_build_object(
          'step_number', s.step_number,
          'required_permission_key', s.required_permission_key,
          'required_approvals', s.required_approvals,
          'prohibit_submitter_approval', s.prohibit_submitter_approval
        ) order by s.step_number), '[]'::jsonb)
        from public.approval_policy_steps s
        where s.band_id = v_band.id
      )
    )
  )
  returning id into v_request_id;

  insert into public.approval_request_steps (
    approval_request_id, step_number, required_permission_key,
    required_approvals, prohibit_submitter_approval
  )
  select
    v_request_id, step_number, required_permission_key,
    required_approvals, prohibit_submitter_approval
  from public.approval_policy_steps
  where band_id = v_band.id
  order by step_number;

  update public.financial_documents
  set status = 'pending_approval',
      approval_request_id = v_request_id,
      approved_at = null,
      approved_by_profile_id = null
  where id = p_document_id;

  return v_request_id;
end;
$$;

create or replace function private.record_approval_decision(
  p_request_step_id uuid,
  p_decision text,
  p_comments text default null
)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_profile_id uuid;
  v_step public.approval_request_steps%rowtype;
  v_request public.approval_requests%rowtype;
  v_approved_count integer;
  v_all_steps_approved boolean;
begin
  if (select auth.uid()) is null then
    raise exception 'Authentication required';
  end if;
  if p_decision not in ('approved','rejected') then
    raise exception 'Decision must be approved or rejected';
  end if;

  v_profile_id := private.current_profile_id();
  if v_profile_id is null then
    raise exception 'No member profile is linked to this account';
  end if;

  select * into v_step
  from public.approval_request_steps
  where id = p_request_step_id
  for update;
  if not found then raise exception 'Approval step not found'; end if;

  select * into v_request
  from public.approval_requests
  where id = v_step.approval_request_id
  for update;
  if not found or v_request.status <> 'pending' then
    raise exception 'Approval request is not pending';
  end if;
  if v_step.status <> 'pending' then
    raise exception 'Approval step is not pending';
  end if;

  if exists (
    select 1 from public.approval_request_steps prior
    where prior.approval_request_id = v_request.id
      and prior.step_number < v_step.step_number
      and prior.status <> 'approved'
  ) then
    raise exception 'Earlier approval steps must be completed first';
  end if;

  if v_step.prohibit_submitter_approval
     and v_request.submitted_by_profile_id = v_profile_id then
    raise exception 'The submitter cannot approve this request';
  end if;

  if not private.has_permission(v_step.required_permission_key, v_request.branch_id) then
    raise exception 'Approver does not have the required permission';
  end if;

  insert into public.approval_decisions (
    approval_request_step_id, approver_profile_id, decision, comments
  )
  values (p_request_step_id, v_profile_id, p_decision, p_comments);

  if p_decision = 'rejected' then
    update public.approval_request_steps
    set status = 'rejected'
    where id = p_request_step_id;

    update public.approval_requests
    set status = 'rejected', completed_at = now()
    where id = v_request.id;

    if v_request.transaction_type = 'financial_document' then
      update public.financial_documents
      set status = 'rejected', approved_at = null, approved_by_profile_id = null
      where id = v_request.target_id
        and approval_request_id = v_request.id;
    elsif v_request.transaction_type = 'budget' then
      update public.budgets
      set status = 'rejected', approved_at = null, approved_by_profile_id = null
      where id = v_request.target_id
        and approval_request_id = v_request.id;
    end if;

    return 'rejected';
  end if;

  select count(*) into v_approved_count
  from public.approval_decisions
  where approval_request_step_id = p_request_step_id
    and decision = 'approved';

  if v_approved_count >= v_step.required_approvals then
    update public.approval_request_steps
    set status = 'approved'
    where id = p_request_step_id;
  end if;

  select not exists (
    select 1 from public.approval_request_steps s
    where s.approval_request_id = v_request.id
      and s.status <> 'approved'
  ) into v_all_steps_approved;

  if v_all_steps_approved then
    update public.approval_requests
    set status = 'approved', completed_at = now()
    where id = v_request.id;

    if v_request.transaction_type = 'financial_document' then
      update public.financial_documents
      set status = 'approved',
          approved_at = now(),
          approved_by_profile_id = v_profile_id
      where id = v_request.target_id
        and approval_request_id = v_request.id;
    elsif v_request.transaction_type = 'budget' then
      update public.budgets
      set status = 'approved',
          approved_at = now(),
          approved_by_profile_id = v_profile_id
      where id = v_request.target_id
        and approval_request_id = v_request.id;
    elsif v_request.transaction_type = 'journal_entry' then
      update public.journal_entries
      set approved_at = now(),
          approved_by_profile_id = v_profile_id
      where id = v_request.target_id
        and status = 'draft'
        and approval_request_id = v_request.id;
    end if;

    return 'approved';
  end if;

  return 'pending';
end;
$$;

create or replace function private.attach_journal_to_financial_document(
  p_document_id uuid,
  p_journal_entry_id uuid
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_doc public.financial_documents%rowtype;
  v_entry public.journal_entries%rowtype;
begin
  if (select auth.uid()) is null then
    raise exception 'Authentication required';
  end if;

  select * into v_doc
  from public.financial_documents
  where id = p_document_id
  for update;
  if not found or v_doc.status <> 'approved' then
    raise exception 'Only approved financial documents can be linked to a journal';
  end if;

  if not private.has_permission('manage_finances', v_doc.branch_id) then
    raise exception 'Insufficient permission to link a journal';
  end if;

  select * into v_entry
  from public.journal_entries
  where id = p_journal_entry_id
  for update;
  if not found or v_entry.status <> 'draft' then
    raise exception 'Journal entry must exist and remain draft';
  end if;

  if v_doc.journal_entry_id is not null then
    raise exception 'Financial document is already linked to a journal';
  end if;

  if v_entry.currency_code <> v_doc.currency_code
     or v_entry.base_currency_code <> v_doc.base_currency_code
     or v_entry.exchange_rate_to_base <> v_doc.exchange_rate_to_base
     or v_entry.branch_id is distinct from v_doc.branch_id then
    raise exception 'Journal and financial document currency, rate or branch do not match';
  end if;

  update public.journal_entries
  set source_type = 'financial_document',
      source_id = p_document_id
  where id = p_journal_entry_id;

  update public.financial_documents
  set journal_entry_id = p_journal_entry_id
  where id = p_document_id;
end;
$$;

-- Replace the posting routine to enforce approval and document linkage.
create or replace function private.post_journal_entry(p_entry_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_entry public.journal_entries%rowtype;
  v_period public.financial_periods%rowtype;
  v_year public.financial_years%rowtype;
  v_base_currency char(3);
  v_line_count integer;
  v_debits numeric(24,4);
  v_credits numeric(24,4);
  v_base_debits numeric(24,4);
  v_base_credits numeric(24,4);
  v_approval_status text;
  v_document_status text;
begin
  if (select auth.uid()) is null then
    raise exception 'Authentication required';
  end if;

  select * into v_entry
  from public.journal_entries
  where id = p_entry_id
  for update;
  if not found then raise exception 'Journal entry not found'; end if;
  if v_entry.status <> 'draft' then
    raise exception 'Only draft journal entries can be posted';
  end if;
  if not private.has_permission('post_journals', v_entry.branch_id) then
    raise exception 'Insufficient permission to post journals';
  end if;

  if v_entry.approval_request_id is not null then
    select status into v_approval_status
    from public.approval_requests
    where id = v_entry.approval_request_id
      and transaction_type = 'journal_entry'
      and target_id = v_entry.id;
    if v_approval_status is distinct from 'approved' then
      raise exception 'Journal approval is incomplete';
    end if;
  end if;

  if v_entry.source_type = 'financial_document' then
    select status into v_document_status
    from public.financial_documents
    where id = v_entry.source_id
      and journal_entry_id = v_entry.id;
    if v_document_status is distinct from 'approved' then
      raise exception 'Linked financial document must be approved before posting';
    end if;
  end if;

  select * into v_period
  from public.financial_periods
  where id = v_entry.period_id;
  if not found or v_period.status <> 'open' then
    raise exception 'Journal entry period is not open';
  end if;
  if v_entry.entry_date < v_period.start_date
     or v_entry.entry_date > v_period.end_date then
    raise exception 'Journal entry date is outside its financial period';
  end if;

  select * into v_year
  from public.financial_years
  where id = v_period.financial_year_id;
  if not found or v_year.status <> 'open' then
    raise exception 'Financial year is not open';
  end if;

  select base_currency_code into v_base_currency
  from public.church_settings where id = 1;
  if v_base_currency is null then
    raise exception 'Complete church settings before posting financial entries';
  end if;
  if v_entry.base_currency_code <> v_base_currency then
    raise exception 'Journal base currency does not match church base currency';
  end if;
  if v_entry.currency_code = v_entry.base_currency_code
     and v_entry.exchange_rate_to_base <> 1 then
    raise exception 'Exchange rate must be 1 for the base currency';
  end if;

  if exists (
    select 1
    from public.journal_lines jl
    join public.chart_of_accounts coa on coa.id = jl.account_id
    where jl.journal_entry_id = p_entry_id and not coa.is_active
  ) then
    raise exception 'Journal contains an inactive chart-of-accounts entry';
  end if;

  if v_entry.branch_id is not null and exists (
    select 1 from public.journal_lines jl
    where jl.journal_entry_id = p_entry_id
      and jl.branch_id is not null
      and jl.branch_id <> v_entry.branch_id
  ) then
    raise exception 'Journal line branch does not match journal branch';
  end if;

  select count(*),
         coalesce(sum(debit_amount),0),
         coalesce(sum(credit_amount),0),
         coalesce(sum(base_debit_amount),0),
         coalesce(sum(base_credit_amount),0)
  into v_line_count, v_debits, v_credits, v_base_debits, v_base_credits
  from public.journal_lines
  where journal_entry_id = p_entry_id;

  if v_line_count < 2 then raise exception 'A journal entry must contain at least two lines'; end if;
  if v_debits <> v_credits then raise exception 'Journal is not balanced in transaction currency'; end if;
  if v_base_debits <> v_base_credits then raise exception 'Journal is not balanced in base currency'; end if;

  if exists (
    select 1 from public.journal_lines jl
    where jl.journal_entry_id = p_entry_id
      and (
        (jl.debit_amount > 0 and
          jl.base_debit_amount <> round(jl.debit_amount * v_entry.exchange_rate_to_base, 4))
        or
        (jl.credit_amount > 0 and
          jl.base_credit_amount <> round(jl.credit_amount * v_entry.exchange_rate_to_base, 4))
      )
  ) then
    raise exception 'Journal line base amount does not match the recorded exchange rate';
  end if;

  update public.journal_entries
  set status = 'posted', posted_at = now()
  where id = p_entry_id;

  if v_entry.source_type = 'financial_document' then
    update public.financial_documents
    set status = 'posted', updated_at = now()
    where id = v_entry.source_id
      and journal_entry_id = p_entry_id
      and status = 'approved';
    if not found then
      raise exception 'Could not finalize linked financial document';
    end if;
  end if;
end;
$$;

create or replace function private.validate_financial_document_journal_link()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_entry public.journal_entries%rowtype;
begin
  if tg_op = 'UPDATE' and old.status = 'posted' then
    raise exception 'Posted financial documents are immutable';
  end if;

  if new.status = 'posted' then
    if new.journal_entry_id is null then
      raise exception 'Posted financial document must have a journal entry';
    end if;
    select * into v_entry
    from public.journal_entries
    where id = new.journal_entry_id;
    if not found or v_entry.status <> 'posted' then
      raise exception 'Financial document can only be posted with a posted journal';
    end if;
    if v_entry.source_type <> 'financial_document'
       or v_entry.source_id is distinct from new.id then
      raise exception 'Journal entry source does not match financial document';
    end if;
  end if;

  if new.journal_entry_id is not null then
    select * into v_entry
    from public.journal_entries
    where id = new.journal_entry_id;
    if not found
       or v_entry.source_type <> 'financial_document'
       or v_entry.source_id is distinct from new.id then
      raise exception 'Journal entry is not linked to this financial document';
    end if;
  end if;

  return new;
end;
$$;

create trigger trg_validate_financial_document_journal
before insert or update on public.financial_documents
for each row execute function private.validate_financial_document_journal_link();

revoke all on function private.submit_financial_document_for_approval(uuid)
  from public, anon, authenticated;
revoke all on function private.record_approval_decision(uuid, text, text)
  from public, anon, authenticated;
revoke all on function private.attach_journal_to_financial_document(uuid, uuid)
  from public, anon, authenticated;
revoke all on function private.post_journal_entry(uuid)
  from public, anon, authenticated;

grant execute on function private.submit_financial_document_for_approval(uuid)
  to authenticated;
grant execute on function private.record_approval_decision(uuid, text, text)
  to authenticated;
grant execute on function private.attach_journal_to_financial_document(uuid, uuid)
  to authenticated;
grant execute on function private.post_journal_entry(uuid)
  to authenticated;

-- -----------------------------------------------------------------------------
-- 20261114142506_scms_017_financial_workflow_hardening.sql
-- -----------------------------------------------------------------------------
create or replace function private.submit_financial_document_for_approval(
  p_document_id uuid
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_doc public.financial_documents%rowtype;
  v_profile_id uuid;
  v_base_currency char(3);
  v_policy public.approval_policies%rowtype;
  v_band public.approval_policy_bands%rowtype;
  v_request_id uuid;
  v_amount_base numeric(20,4);
  v_steps_count integer;
begin
  if (select auth.uid()) is null then
    raise exception 'Authentication required';
  end if;
  v_profile_id := private.current_profile_id();
  if v_profile_id is null then
    raise exception 'No member profile is linked to this account';
  end if;

  select * into v_doc
  from public.financial_documents
  where id = p_document_id
  for update;
  if not found then raise exception 'Financial document not found'; end if;
  if v_doc.status not in ('draft','rejected') then
    raise exception 'Only draft or rejected documents can be submitted';
  end if;
  if v_doc.journal_entry_id is not null then
    raise exception 'Document is already linked to a journal entry';
  end if;
  if v_doc.created_by_profile_id is distinct from v_profile_id
     and not private.has_permission('manage_finances', v_doc.branch_id) then
    raise exception 'Insufficient permission to submit this document';
  end if;

  select base_currency_code into v_base_currency
  from public.church_settings where id = 1;
  if v_base_currency is null then
    raise exception 'Church settings must be configured before financial operations';
  end if;
  if v_doc.base_currency_code <> v_base_currency then
    raise exception 'Document base currency does not match church base currency';
  end if;
  if v_doc.currency_code = v_base_currency and v_doc.exchange_rate_to_base <> 1 then
    raise exception 'Exchange rate must be 1 for the base currency';
  end if;

  if v_doc.financial_account_id is not null and not exists (
    select 1 from public.financial_accounts fa
    where fa.id = v_doc.financial_account_id
      and fa.is_active
      and fa.currency_code = v_doc.currency_code
      and (fa.branch_id is null or fa.branch_id is not distinct from v_doc.branch_id)
  ) then
    raise exception 'Financial account is inactive or incompatible with document branch/currency';
  end if;

  v_amount_base := round(v_doc.amount * v_doc.exchange_rate_to_base, 4);

  select * into v_policy
  from public.approval_policies p
  where p.transaction_type = 'financial_document'
    and p.is_active
    and p.effective_from <= current_date
    and (p.effective_to is null or p.effective_to >= current_date)
    and (p.branch_id = v_doc.branch_id or p.branch_id is null)
  order by (p.branch_id is not null) desc, p.version desc
  limit 1;
  if not found then
    raise exception 'No active financial-document approval policy is configured for this scope';
  end if;

  select * into v_band
  from public.approval_policy_bands b
  where b.policy_id = v_policy.id
    and v_amount_base >= b.min_amount_base
    and (b.max_amount_base is null or v_amount_base < b.max_amount_base)
  limit 1;
  if not found then
    raise exception 'No approval threshold band covers this transaction amount';
  end if;

  select count(*) into v_steps_count
  from public.approval_policy_steps
  where band_id = v_band.id;

  if v_steps_count = 0 then
    update public.financial_documents
    set status = 'approved',
        approved_at = now(),
        approved_by_profile_id = null,
        approval_request_id = null
    where id = p_document_id;
    return null;
  end if;

  insert into public.approval_requests (
    transaction_type, target_id, branch_id, policy_id, policy_version,
    band_id, amount_base, submitted_by_profile_id, policy_snapshot
  )
  values (
    'financial_document', p_document_id, v_doc.branch_id,
    v_policy.id, v_policy.version, v_band.id, v_amount_base,
    v_profile_id,
    jsonb_build_object(
      'policy_name', v_policy.name,
      'policy_version', v_policy.version,
      'min_amount_base', v_band.min_amount_base,
      'max_amount_base', v_band.max_amount_base,
      'steps', (
        select coalesce(jsonb_agg(jsonb_build_object(
          'step_number', s.step_number,
          'required_permission_key', s.required_permission_key,
          'required_approvals', s.required_approvals,
          'prohibit_submitter_approval', s.prohibit_submitter_approval
        ) order by s.step_number), '[]'::jsonb)
        from public.approval_policy_steps s where s.band_id = v_band.id
      )
    )
  )
  returning id into v_request_id;

  insert into public.approval_request_steps (
    approval_request_id, step_number, required_permission_key,
    required_approvals, prohibit_submitter_approval
  )
  select v_request_id, step_number, required_permission_key,
    required_approvals, prohibit_submitter_approval
  from public.approval_policy_steps
  where band_id = v_band.id
  order by step_number;

  update public.financial_documents
  set status = 'pending_approval',
      approval_request_id = v_request_id,
      approved_at = null,
      approved_by_profile_id = null
  where id = p_document_id;

  return v_request_id;
end;
$$;

create or replace function private.submit_budget_for_approval(p_budget_id uuid)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_budget public.budgets%rowtype;
  v_profile_id uuid;
  v_base_currency char(3);
  v_policy public.approval_policies%rowtype;
  v_band public.approval_policy_bands%rowtype;
  v_request_id uuid;
  v_amount_base numeric(20,4);
  v_steps_count integer;
begin
  if (select auth.uid()) is null then
    raise exception 'Authentication required';
  end if;
  v_profile_id := private.current_profile_id();
  if v_profile_id is null then
    raise exception 'No member profile is linked to this account';
  end if;

  select * into v_budget
  from public.budgets where id = p_budget_id for update;
  if not found then raise exception 'Budget not found'; end if;
  if v_budget.status not in ('draft','rejected') then
    raise exception 'Only draft or rejected budgets can be submitted';
  end if;
  if v_budget.submitted_by_profile_id is not null
     and v_budget.submitted_by_profile_id <> v_profile_id
     and not private.has_permission('manage_finances', v_budget.branch_id) then
    raise exception 'Insufficient permission to submit this budget';
  end if;

  select base_currency_code into v_base_currency
  from public.church_settings where id = 1;
  if v_base_currency is null then
    raise exception 'Church settings must be configured before financial operations';
  end if;
  if v_budget.base_currency_code <> v_base_currency then
    raise exception 'Budget base currency does not match church base currency';
  end if;
  if v_budget.currency_code = v_base_currency and v_budget.exchange_rate_to_base <> 1 then
    raise exception 'Exchange rate must be 1 for the base currency';
  end if;

  select coalesce(sum(bl.allocated_amount),0) * v_budget.exchange_rate_to_base
  into v_amount_base
  from public.budget_lines bl
  where bl.budget_id = p_budget_id;
  v_amount_base := round(v_amount_base, 4);
  if v_amount_base <= 0 then
    raise exception 'Budget must contain a positive total allocation';
  end if;

  select * into v_policy
  from public.approval_policies p
  where p.transaction_type = 'budget'
    and p.is_active
    and p.effective_from <= current_date
    and (p.effective_to is null or p.effective_to >= current_date)
    and (p.branch_id = v_budget.branch_id or p.branch_id is null)
  order by (p.branch_id is not null) desc, p.version desc
  limit 1;
  if not found then
    raise exception 'No active budget approval policy is configured for this scope';
  end if;

  select * into v_band
  from public.approval_policy_bands b
  where b.policy_id = v_policy.id
    and v_amount_base >= b.min_amount_base
    and (b.max_amount_base is null or v_amount_base < b.max_amount_base)
  limit 1;
  if not found then
    raise exception 'No approval threshold band covers this budget amount';
  end if;

  select count(*) into v_steps_count
  from public.approval_policy_steps where band_id = v_band.id;

  if v_steps_count = 0 then
    update public.budgets
    set status = 'approved',
        submitted_by_profile_id = v_profile_id,
        approved_at = now(),
        approved_by_profile_id = null,
        approval_request_id = null
    where id = p_budget_id;
    return null;
  end if;

  insert into public.approval_requests (
    transaction_type, target_id, branch_id, policy_id, policy_version,
    band_id, amount_base, submitted_by_profile_id, policy_snapshot
  )
  values (
    'budget', p_budget_id, v_budget.branch_id,
    v_policy.id, v_policy.version, v_band.id, v_amount_base,
    v_profile_id,
    jsonb_build_object(
      'policy_name', v_policy.name,
      'policy_version', v_policy.version,
      'min_amount_base', v_band.min_amount_base,
      'max_amount_base', v_band.max_amount_base,
      'steps', (
        select coalesce(jsonb_agg(jsonb_build_object(
          'step_number', s.step_number,
          'required_permission_key', s.required_permission_key,
          'required_approvals', s.required_approvals,
          'prohibit_submitter_approval', s.prohibit_submitter_approval
        ) order by s.step_number), '[]'::jsonb)
        from public.approval_policy_steps s where s.band_id = v_band.id
      )
    )
  )
  returning id into v_request_id;

  insert into public.approval_request_steps (
    approval_request_id, step_number, required_permission_key,
    required_approvals, prohibit_submitter_approval
  )
  select v_request_id, step_number, required_permission_key,
    required_approvals, prohibit_submitter_approval
  from public.approval_policy_steps
  where band_id = v_band.id
  order by step_number;

  update public.budgets
  set status = 'pending_approval',
      submitted_by_profile_id = v_profile_id,
      approval_request_id = v_request_id,
      approved_at = null,
      approved_by_profile_id = null
  where id = p_budget_id;

  return v_request_id;
end;
$$;

create or replace function private.validate_financial_document_journal_link()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_entry public.journal_entries%rowtype;
begin
  if tg_op = 'DELETE' then
    if old.status = 'posted' then
      raise exception 'Posted financial documents cannot be deleted';
    end if;
    return old;
  end if;

  if tg_op = 'UPDATE' and old.status = 'posted' then
    raise exception 'Posted financial documents are immutable';
  end if;

  if new.status = 'posted' then
    if new.journal_entry_id is null then
      raise exception 'Posted financial document must have a journal entry';
    end if;
    select * into v_entry from public.journal_entries
    where id = new.journal_entry_id;
    if not found or v_entry.status <> 'posted' then
      raise exception 'Financial document can only be posted with a posted journal';
    end if;
    if v_entry.source_type <> 'financial_document'
       or v_entry.source_id is distinct from new.id then
      raise exception 'Journal entry source does not match financial document';
    end if;
  end if;

  if new.journal_entry_id is not null then
    select * into v_entry from public.journal_entries
    where id = new.journal_entry_id;
    if not found
       or v_entry.source_type <> 'financial_document'
       or v_entry.source_id is distinct from new.id then
      raise exception 'Journal entry is not linked to this financial document';
    end if;
  end if;

  return new;
end;
$$;

drop trigger trg_validate_financial_document_journal on public.financial_documents;
create trigger trg_validate_financial_document_journal
before insert or update or delete on public.financial_documents
for each row execute function private.validate_financial_document_journal_link();

create or replace function private.prevent_budget_line_mutation()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_budget_id uuid;
  v_status text;
begin
  if tg_op = 'DELETE' then
    v_budget_id := old.budget_id;
  else
    v_budget_id := new.budget_id;
  end if;

  select status into v_status
  from public.budgets where id = v_budget_id;

  if v_status not in ('draft','rejected') then
    raise exception 'Budget lines can only be changed while the budget is draft or rejected';
  end if;

  return case when tg_op = 'DELETE' then old else new end;
end;
$$;

create trigger trg_budget_lines_draft_only
before insert or update or delete on public.budget_lines
for each row execute function private.prevent_budget_line_mutation();

revoke all on function private.submit_budget_for_approval(uuid)
  from public, anon, authenticated;
grant execute on function private.submit_budget_for_approval(uuid)
  to authenticated;

